const settings = $('Settings').first().json;
const match = String(settings.match_text || '').trim();

if (!match) {
  throw new Error('Fill in match_text in the Settings node first (part of your n8n webhook URL).');
}

const out = [];
for (const item of $input.all()) {
  const hooks = item.json.webhooks || [];
  for (const w of hooks) {
    out.push({
      json: {
        webhook_id: w.id,
        endpoint: w.endpoint,
        team_id: w.team_id,
        health: w.health ? w.health.status : null,
        events: w.events,
        matches: String(w.endpoint || '').includes(match)
      }
    });
  }
}

return out;

const item = $input.item.json;
const content = item.description || "";

const taskLinkMatch = content.match(/Task Link:\s*(https?:\/\/\S+)/);
const taskLink = taskLinkMatch ? taskLinkMatch[1].trim() : "";

const descMatch = content.match(/Task Link:.*?\n+([\s\S]*?)(?=Deliverables:)/);
const description = descMatch ? descMatch[1].trim() : "";

const deliverablesMatch = content.match(/Deliverables:\s*([\s\S]*?)(?=Notes:)/);
let deliverables = [];
if (deliverablesMatch) {
  const raw = deliverablesMatch[1].trim();
  deliverables = raw.split(/,|\n/).map(d => d.trim()).filter(Boolean);
}

const notesMatch = content.match(/Notes:\s*([\s\S]*?)(?=Resources:)/);
let notes = "";
if (notesMatch) {
  notes = notesMatch[1].trim().split("\n").map(n => n.trim()).filter(Boolean).join("\n");
}

const resourcesMatch = content.match(/Resources:\s*([\s\S]*)$/);
let resources = [];
if (resourcesMatch) {
  resources = resourcesMatch[1].trim().split("\n").map(r => r.trim()).filter(Boolean);
}

return {
  task_id: item.id,
  task_name: item.name || "",
  clickup_task_link: `https://app.clickup.com/t/${item.id}`,
  task_link: taskLink,
  description: description,
  deliverables: deliverables,
  notes: notes,
  resources: resources,
  status: item.status?.status || "",
  assignees: (item.assignees || []).map(a => a.username)
};

const subtasks = $('Get Task (Closed + Subtasks)').first().json.subtasks || [];

const taskArray = subtasks.map(subtask => {
  return {
    json: subtask
  };
});

return taskArray;

const subtasks = $('Get Task (Recurring)1').first().json.subtasks || [];

const taskArray = subtasks.map(subtask => {
  return {
    json: subtask
  };
});

return taskArray;

const task = $input.item.json;
const history = $('ClickUp Trigger').item.json.history_items || [];

let people = (task.assignees || []).map(a => ({ id: a.id, username: a.username }));

for (const h of history) {
  // someone was removed: take them off even if ClickUp still lists them
  if (h.field === 'assignee_rem') {
    const u = h.before || h.after;
    if (u) people = people.filter(a => a.id !== u.id);
  }
  // someone was added: make sure they're on the list
  if (h.field === 'assignee_add' && h.after && !people.some(a => a.id === h.after.id)) {
    people.push({ id: h.after.id, username: h.after.username });
  }
}

const list = people.map(a => a.username);

return {
  json: {
    ...task,
    assignee_list: list,
    assigned_text: list.length ? list.join(', ') : 'Unassigned'
  }
};

const task = $('Get Task (Assignee)').first().json;
const history = $('ClickUp Trigger').first().json.history_items || [];
const out = [];

// only notify people who were just ASSIGNED; removals send nothing
for (const h of history) {
  if (h.field === 'assignee_add' && h.after?.email) {
    out.push({ json: { email: h.after.email, label: 'Assigned Task', task_id: task.id, task_name: task.name } });
  }
}

return out;

// Single source of truth for status labels (lowercase ClickUp status -> label shown in sheets)
const status_map = {
  'pending': 'Pending',
  'in progress': 'In Progress',
  'revision': 'Revision',
  'waiting': 'Waiting',
  'in review': 'In Review',
  'checking': 'Checking',
  'closed': 'Closed',
  'daily': 'Daily',
  'weekly': 'Weekly',
  'monthly': 'Monthly',
  'on hold': 'On-Hold',
  'on-hold': 'On-Hold'
};
return $input.all().map(i => ({ json: { ...i.json, status_map } }));

// Single place for the Google Sheet ID ("Notes for Today")
const sheet_id = '15DCkm5fI4zx9mcpxnvh6zIt0I_wjn34YuMAT_G4GTR8';
return $input.all().map(i => ({ json: { ...i.json, sheet_id } }));

// Drop duplicate ClickUp webhook deliveries (same task + same history item ids) seen in the last 10 minutes
const data = $getWorkflowStaticData('global');
data.seen = data.seen || {};
const now = Date.now();
const TTL = 10 * 60 * 1000;
for (const k of Object.keys(data.seen)) {
  if (now - data.seen[k] > TTL) delete data.seen[k];
}
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const hist = j.history_items || [];
  const key = [j.event, j.task_id, ...hist.map(h => h.id || (h.field + ':' + JSON.stringify(h.after ?? null)))].join('|');
  if (data.seen[key]) continue;
  data.seen[key] = now;
  out.push(item);
}
return out;
